/**
 * @fileoverview Test the overriding of an existing Class
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-existing-class-override'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester({
    settings: {
        extjs: {
            toolkit: 'modern',
            fromVersion: '6.0',
            toVersion: '7.9.0'
        }
    }
});
ruleTester.run('no-existing-class-override', rule, {

    valid: [
        {
            code: `
                Ext.define('MyCustomClass', { extend: 'Ext.SomeClass'});
            `
        }
    ],

    invalid: [
        {
            code: `
                Ext.define('MyCustomClass', { override: 'Ext.SomeClass' });

                // TODO - should we report on the name of the class being overridden?
                // the override-method-call rule already reports "Call to 'Ext.override()' method found"
                Ext.override(panel, {
                    initialize: function () {
                        // extra processing...
               
                        this.callParent();
                    }
                });

                // new 7.4 classes (do not need to test all since this rule reports on ANY override of a class)
                Ext.define('MyCustomClass', { override: 'Ext.grid.plugin.filterbar.filters.Base' });
                Ext.define('MyCustomClass', { override: 'Ext.grid.plugin.Summaries' });
                Ext.define('MyCustomClass', { override: 'Ext.util.GrouperCollection' });
            `,
            errors: [
                { message: /Override of Class 'Ext.SomeClass' found/ },
                
                // new 7.4 classes
                { message: /Override of Class 'Ext.grid.plugin.filterbar.filters.Base' found/ },
                { message: /Override of Class 'Ext.grid.plugin.Summaries' found/ },
                { message: /Override of Class 'Ext.util.GrouperCollection' found/ }
            ]
        }
    ]
});
